/* ============================================================
   dexie.min.js — micro-implémentation autonome (offline)
   Sous-ensemble de l'API Dexie utilisé par Sensations Macarons.
   Aucune dépendance réseau. Fonctionne sur Safari iOS / IndexedDB.

   API couverte :
     new Dexie(name)
     db.version(n).stores({table:'++id, idx, ...'})
     db.table(name) / db.<tableName> / db.tables (liste des tables)
     db.on('blocked', cb) / db.close() / db.open()
     table.add / update / put / delete / get / toArray / count / clear
     table.bulkAdd / bulkPut / bulkDelete
     table.hook('creating'|'updating'|'deleting', fn)   ← [v1381]
     table.orderBy(idx).reverse().limit(n).toArray() / .primaryKeys()
     table.where(idx).equals(v).and(fn).toArray() / .delete() / .sortBy(k)
     table.where(idx).between(lo, hi, incLo, incHi)
     db.transaction('rw', t1, t2, ..., async fn)
     Dexie.ignoreTransaction(fn)                        ← [v1381]

   [v1381] POURQUOI CETTE EXTENSION : app.js (v1372+) s'appuie sur les
   hooks Dexie (journal d'audit, validation à l'entrée), sur bulkPut/
   bulkDelete (stockage unifié kv), sur primaryKeys (rétention du
   journal) et sur Dexie.ignoreTransaction (écrire au journal depuis
   un hook). Cette micro-implémentation ne les fournissait PAS : ces
   appels échouaient en silence depuis un mois (table kv restée vide,
   aucun hook jamais installé). Le contrat est désormais tenu ICI, à
   la sémantique Dexie près :
     • hook 'creating'  : fn(clePrimaire, objet, trans) — `this.onsuccess(id)`
       est rappelé avec la clé générée après insertion.
     • hook 'updating'  : fn(modifs, clePrimaire, objetAVANT, trans).
     • hook 'deleting'  : fn(clePrimaire, objet, trans).
     • LEVER une exception dans un hook AVORTE l'opération (et toute la
       transaction explicite en cours) — c'est le mécanisme de refus de
       la validation. Rien n'est écrit.
     • trans.on('complete'|'abort'|'error', cb) : rappels de fin de
       transaction (le tampon d'audit ne s'écrit qu'au commit).
     • put() déclenche 'creating' si la clé n'existe pas encore,
       'updating' sinon (upsert, comme Dexie).
     • Dexie.ignoreTransaction(fn) : exécute fn HORS de la transaction
       en cours (report en macrotâche — divergence assumée : Dexie
       utilise des zones async ; ici le report suffit, l'appelant
       n'attend pas le résultat).

   DIVERGENCES DÉCLARÉES (assumées, documentées) :
     • clear() ne déclenche PAS les hooks 'deleting' ligne à ligne —
       les seuls clear() massifs de l'app sont les restaurations, où
       app.js suspend de toute façon les hooks (_importEnCours).
     • Les hooks ne renvoient pas de valeur de substitution (Dexie le
       permet ; app.js ne s'en sert pas).
   ============================================================ */
(function (global) {
  'use strict';

  function parseSchema(spec) {
    const parts = spec.split(',').map(s => s.trim()).filter(Boolean);
    const pk = parts[0];
    const auto = pk.startsWith('++');
    const key = pk.replace(/^\+\+/, '').replace(/^&/, '');
    const indexes = parts.slice(1).map(s => s.replace(/^&/, '').replace(/^\*/, ''));
    return { key, auto, indexes };
  }

  function reqProm(req) {
    return new Promise((res, rej) => {
      req.onsuccess = () => res(req.result);
      req.onerror = () => rej(req.error);
    });
  }

  // [v1381] Enveloppe de transaction passée aux hooks : expose .on(evt, cb) branché sur les
  // événements IDB (addEventListener : on ne CLOBBER jamais les oncomplete internes), et sert de
  // porte-propriétés libre (le tampon d'audit y accroche trans._smAudit). UNE enveloppe par
  // transaction IDB : les opérations d'une même transaction explicite partagent le même tampon.
  const _txWraps = (typeof WeakMap !== 'undefined') ? new WeakMap() : null;
  // [v1438] Transactions IDB dont on sait qu'elles sont TERMINÉES (complete/abort/error).
  // `_activeTx` (sur l'instance Dexie) est un champ PARTAGÉ, pas propre à un appel : sous
  // exécution concurrente (plusieurs db.transaction() en vol en même temps, ou un rappel
  // différé par Dexie.ignoreTransaction/setTimeout qui reprend la main après coup), une
  // opération peut se retrouver avec `_activeTx` pointant vers la transaction d'un AUTRE
  // appel, déjà commitée ou ne portant pas la table visée. Voir le renfort dans _txStore().
  const _txFinished = (typeof WeakSet !== 'undefined') ? new WeakSet() : null;
  function _watchTxFinish(tx) {
    if (!_txFinished) return;
    const mark = () => _txFinished.add(tx);
    try { tx.addEventListener('complete', mark); tx.addEventListener('abort', mark); tx.addEventListener('error', mark); }
    catch (e) { /* environnement sans EventTarget : tant pis, on retombe sur le comportement d'avant */ }
  }
  function wrapTx(tx) {
    if (!tx) return null;
    if (_txWraps && _txWraps.has(tx)) return _txWraps.get(tx);
    const w = {
      on(evt, cb) {
        try { tx.addEventListener(evt, cb); } catch (e) { /* environnement sans EventTarget : rappel perdu, jamais bloquant */ }
      }
    };
    if (_txWraps) _txWraps.set(tx, w);
    return w;
  }

  class Collection {
    constructor(table, filterFn, orderIndex, reverse, limitN) {
      this.table = table;
      this.filterFn = filterFn || (() => true);
      this.orderIndex = orderIndex || null;
      this._reverse = !!reverse;
      this._limit = limitN || null;
    }
    and(fn) {
      const prev = this.filterFn;
      return new Collection(this.table, x => prev(x) && fn(x), this.orderIndex, this._reverse, this._limit);
    }
    reverse() { return new Collection(this.table, this.filterFn, this.orderIndex, !this._reverse, this._limit); }
    limit(n) { return new Collection(this.table, this.filterFn, this.orderIndex, this._reverse, n); }
    async _all() {
      const rows = (await this.table.toArray()).filter(this.filterFn);
      if (this.orderIndex) {
        rows.sort((a, b) => {
          const av = a[this.orderIndex], bv = b[this.orderIndex];
          if (av === bv) return 0;
          if (av == null) return -1;
          if (bv == null) return 1;
          return av < bv ? -1 : 1;
        });
      }
      if (this._reverse) rows.reverse();
      return this._limit != null ? rows.slice(0, this._limit) : rows;
    }
    toArray() { return this._all(); }
    async sortBy(key) {
      const rows = await this._all();
      return rows.sort((a, b) => {
        const av = a[key], bv = b[key];
        if (av === bv) return 0; if (av == null) return -1; if (bv == null) return 1;
        return av < bv ? -1 : 1;
      });
    }
    async first() { return (await this._all())[0]; }
    // [v1381] Clés primaires de la collection (ordre/limite respectés) — rétention du journal.
    async primaryKeys() {
      const rows = await this._all();
      const k = this.table.schema.key;
      return rows.map(r => r[k]);
    }
    async delete() {
      const rows = await this._all();
      for (const r of rows) await this.table.delete(r[this.table.schema.key]);
      return rows.length;
    }
    async count() { return (await this._all()).length; }
  }

  class WhereClause {
    constructor(table, index) { this.table = table; this.index = index; }
    equals(v) { return new Collection(this.table, x => x[this.index] === v); }
    above(v) { return new Collection(this.table, x => x[this.index] > v); }
    below(v) { return new Collection(this.table, x => x[this.index] < v); }
    // [v1381] Bornes incluses par défaut, comme Dexie (utilisé par les fenêtres de dates).
    between(lo, hi, incLo, incHi) {
      const iLo = (incLo !== false), iHi = (incHi !== false);
      return new Collection(this.table, x => {
        const v = x[this.index];
        if (v == null) return false;
        const okLo = iLo ? v >= lo : v > lo;
        const okHi = iHi ? v <= hi : v < hi;
        return okLo && okHi;
      });
    }
    anyOf(list) {
      const set = new Set(list);
      // ':id' = clé primaire (motif Dexie utilisé par bulkDeleteSafe).
      const key = (this.index === ':id') ? this.table.schema.key : this.index;
      return new Collection(this.table, x => set.has(x[key]));
    }
  }

  class Table {
    constructor(db, name, schema) {
      this.db = db; this.name = name; this.schema = schema;
      this._hooks = { creating: [], updating: [], deleting: [] };   // [v1381]
    }
    // [v1381] S'abonner à un événement d'écriture. Plusieurs abonnés possibles (validation PUIS
    // audit, dans l'ordre d'abonnement). Lever une exception dans un abonné avorte l'opération.
    hook(evt, fn) {
      if (this._hooks[evt]) this._hooks[evt].push(fn);
      return { unsubscribe: () => { const a = this._hooks[evt]; const i = a ? a.indexOf(fn) : -1; if (i > -1) a.splice(i, 1); } };
    }
    // Transaction + store pour UNE opération : réutilise la transaction explicite active, sinon en
    // ouvre une propre à l'opération (own=true → c'est à nous de l'avorter si un hook refuse).
    // [v1438] `active` n'est fiable QUE si (a) elle n'est pas déjà terminée, (b) elle porte
    // réellement la table demandée, (c) son mode couvre ce qu'on demande (une lecture peut
    // emprunter une transaction en écriture, l'inverse non). Sinon on ouvre notre propre
    // transaction plutôt que de laisser `tx.objectStore()` lever une IDBTransaction déjà morte
    // ou étrangère — c'est exactement l'erreur « The transaction finished » / « The specified
    // object store was not found » vue en prod (atParfumsDispo, Productions, flush d'audit).
    _txStore(mode) {
      const active = this.db._activeTx;
      const reusable = !!(active
        && !(_txFinished && _txFinished.has(active))
        && active.objectStoreNames && active.objectStoreNames.contains(this.name)
        && (mode === 'readonly' || active.mode === 'readwrite'));
      const tx = reusable ? active : this.db._idb.transaction([this.name], mode);
      return { tx, store: tx.objectStore(this.name), own: !reusable };
    }
    // Exécute les abonnés d'un événement. Chaque abonné reçoit un contexte {onsuccess} (Dexie y
    // rappelle la clé générée). Une exception remonte TELLE QUELLE : l'appelant avorte.
    _fireHooks(evt, args) {
      const ctxs = [];
      for (const fn of this._hooks[evt]) {
        const ctx = { onsuccess: null, onerror: null };
        fn.apply(ctx, args);
        ctxs.push(ctx);
      }
      return ctxs;
    }
    async add(obj) {
      const o = Object.assign({}, obj);
      const pk = (this.schema.auto && o[this.schema.key] == null) ? undefined : o[this.schema.key];
      if (this.schema.auto && (o[this.schema.key] == null)) delete o[this.schema.key];
      const { tx, store, own } = this._txStore('readwrite');
      let ctxs = [];
      if (this._hooks.creating.length) {
        try { ctxs = this._fireHooks('creating', [pk, o, wrapTx(tx)]); }
        catch (e) { if (own) { try { tx.abort(); } catch (_) {} } throw e; }   // refus : rien n'est écrit
      }
      const id = await reqProm(store.add(o));
      ctxs.forEach(c => { try { if (c.onsuccess) c.onsuccess(id); } catch (_) {} });
      return id;
    }
    async bulkAdd(arr) { const ids = []; for (const o of arr) ids.push(await this.add(o)); return ids; }
    async update(id, changes) {
      const { tx, store, own } = this._txStore('readwrite');
      const cur = await reqProm(store.get(id));
      if (!cur) return 0;
      if (this._hooks.updating.length) {
        try { this._fireHooks('updating', [changes, id, cur, wrapTx(tx)]); }
        catch (e) { if (own) { try { tx.abort(); } catch (_) {} } throw e; }
      }
      Object.assign(cur, changes);
      await reqProm(store.put(cur));
      return 1;
    }
    // [v1381] put = upsert : 'creating' si la clé n'existe pas encore, 'updating' sinon (Dexie).
    async put(obj) {
      const { tx, store, own } = this._txStore('readwrite');
      if (this._hooks.creating.length || this._hooks.updating.length) {
        const key = obj[this.schema.key];
        const existing = (key != null) ? await reqProm(store.get(key)) : undefined;
        let ctxs = [];
        try {
          if (existing !== undefined) this._fireHooks('updating', [obj, key, existing, wrapTx(tx)]);
          else ctxs = this._fireHooks('creating', [key, obj, wrapTx(tx)]);
        } catch (e) { if (own) { try { tx.abort(); } catch (_) {} } throw e; }
        const id = await reqProm(store.put(obj));
        ctxs.forEach(c => { try { if (c.onsuccess) c.onsuccess(id); } catch (_) {} });
        return id;
      }
      return reqProm(store.put(obj));
    }
    async bulkPut(arr) { const ids = []; for (const o of (arr || [])) ids.push(await this.put(o)); return ids; }
    async delete(id) {
      const { tx, store, own } = this._txStore('readwrite');
      if (this._hooks.deleting.length) {
        const cur = await reqProm(store.get(id));
        if (cur !== undefined) {
          try { this._fireHooks('deleting', [id, cur, wrapTx(tx)]); }
          catch (e) { if (own) { try { tx.abort(); } catch (_) {} } throw e; }
        }
      }
      return reqProm(store.delete(id));
    }
    async bulkDelete(ids) { for (const id of (ids || [])) await this.delete(id); }
    // Divergence déclarée : clear() sans hooks ligne à ligne (voir l'en-tête du fichier).
    async clear() { const { store } = this._txStore('readwrite'); return reqProm(store.clear()); }
    async get(id) { const { store } = this._txStore('readonly'); return reqProm(store.get(id)); }
    async toArray() { const { store } = this._txStore('readonly'); return reqProm(store.getAll()); }
    async count() { const { store } = this._txStore('readonly'); return reqProm(store.count()); }
    where(index) { return new WhereClause(this, index); }
    orderBy(index) { return new Collection(this, null, index, false, null); }
  }

  class Dexie {
    constructor(name) {
      this.name = name; this._schemas = {}; this._tables = {};
      this._verno = 1; this._idb = null; this._activeTx = null;
      this._openPromise = null;
      this._events = {};   // [v1381] db.on('blocked'|'versionchange', cb)
    }
    // [v1381] Liste des tables (le journal d'audit s'installe en itérant dessus).
    get tables() { return Object.keys(this._tables).map(t => this._tables[t]); }
    on(evt, cb) { (this._events[evt] = this._events[evt] || []).push(cb); }
    _emit(evt, arg) { (this._events[evt] || []).forEach(cb => { try { cb(arg); } catch (_) {} }); }
    version(n) {
      if (n > this._verno) this._verno = n;
      return { stores: defs => {
        for (const t in defs) this._schemas[t] = parseSchema(defs[t]);
        for (const t in this._schemas) {
          if (!this._tables[t]) {
            const tbl = new Table(this, t, this._schemas[t]);
            this._tables[t] = tbl;
            if (!(t in this)) this[t] = tbl;
          }
        }
        if (!this._openScheduled) {
          this._openScheduled = true;
          Promise.resolve().then(() => this._open());
        }
        return this;
      }};
    }
    _open() {
      this._openPromise = new Promise((res, rej) => {
        const req = indexedDB.open(this.name, this._verno);
        req.onblocked = () => this._emit('blocked');
        req.onupgradeneeded = ev => {
          const idb = ev.target.result;
          for (const t in this._schemas) {
            const sc = this._schemas[t];
            let store;
            if (!idb.objectStoreNames.contains(t)) {
              store = idb.createObjectStore(t, { keyPath: sc.key, autoIncrement: sc.auto });
            } else {
              store = req.transaction.objectStore(t);
            }
            for (const idx of sc.indexes) {
              if (!store.indexNames.contains(idx)) {
                try { store.createIndex(idx, idx, { unique: false }); } catch (e) {}
              }
            }
          }
        };
        req.onsuccess = () => { this._idb = req.result; res(this._idb); };
        req.onerror = () => rej(req.error);
      });
      return this._openPromise;
    }
    table(name) { return this._tables[name]; }
    // [v1381] Fermer/rouvrir (chemin de réparation « base bloquée » de l'app).
    close() { try { if (this._idb) this._idb.close(); } catch (_) {} this._idb = null; this._openPromise = null; }
    open() { if (this._idb) return Promise.resolve(this._idb); return this._open(); }
    async _ready() {
      if (this._idb) return;
      while (!this._openPromise) await Promise.resolve();
      await this._openPromise;
    }
    async transaction(mode, ...args) {
      const fn = args.pop();
      const tables = args.map(a => (typeof a === 'string') ? a : a.name);
      await this._ready();
      const m = mode === 'rw' ? 'readwrite' : 'readonly';
      const tx = this._idb.transaction(tables, m);
      _watchTxFinish(tx);   // [v1438]
      const prev = this._activeTx;
      this._activeTx = tx;
      const done = new Promise((res, rej) => {
        tx.oncomplete = () => res();
        tx.onerror = () => rej(tx.error);
        tx.onabort = () => rej(tx.error || new Error('Transaction abort'));
      });
      let result;
      try {
        result = await fn();
      } catch (e) {
        this._activeTx = prev;
        try { tx.abort(); } catch (_) {}
        // La promesse `done` va rejeter (abort) : on la neutralise pour ne pas générer
        // d'« unhandled rejection » — l'erreur d'origine est celle qui compte.
        done.catch(() => {});
        throw e;
      }
      this._activeTx = prev;
      await done;
      return result;
    }
  }

  // [v1381] Exécuter fn HORS de la transaction en cours. Report en macrotâche : au moment où fn
  // s'exécute, la transaction qui enveloppait l'appel n'est plus active côté enveloppe (_activeTx),
  // donc les opérations de fn ouvrent leur PROPRE transaction. C'est l'issue documentée pour
  // écrire au journal depuis un hook (la zone de la transaction mourante ne contient pas auditLog).
  Dexie.ignoreTransaction = function (fn) {
    return new Promise((res, rej) => {
      setTimeout(() => { try { res(fn()); } catch (e) { rej(e); } }, 0);
    });
  };

  // [v1438] Exposé UNIQUEMENT pour les tests (tests/v1438-activeTx-course.test.js) — permet de
  // simuler fidèlement une transaction « suivie » comme le serait une vraie transaction explicite,
  // sans dupliquer la logique de _watchTxFinish. Ne change rien au comportement de l'app.
  Dexie._internalTestHooks = { watchTxFinish: _watchTxFinish };

  // Patch : s'assurer que toute opération attend l'ouverture de la base.
  // IMPORTANT : si une transaction est DÉJÀ active, on NE refait PAS « await _ready() ».
  // La base est forcément ouverte à ce stade, et intercaler un await non-IndexedDB
  // ferait expirer (auto-commit) la transaction en cours. On exécute alors directement.
  const origMethods = ['add', 'bulkAdd', 'update', 'put', 'bulkPut', 'delete', 'bulkDelete', 'clear', 'get', 'toArray', 'count'];
  origMethods.forEach(m => {
    const orig = Table.prototype[m];
    Table.prototype[m] = function (...a) {
      if (this.db._activeTx) return orig.apply(this, a);   // transaction en cours : pas d'await parasite
      return this.db._ready().then(() => orig.apply(this, a));
    };
  });
  const origColAll = Collection.prototype._all;
  Collection.prototype._all = function () {
    if (this.table.db._activeTx) return origColAll.call(this);
    return this.table.db._ready().then(() => origColAll.call(this));
  };

  global.Dexie = Dexie;
})(typeof self !== 'undefined' ? self : this);
